   206→ *
   207→ * FIX #9 (Post-Recalibration Week 3-4): AI Capability-Scaled Deployment
   208→ * Research: McKinsey (2024), Foundation Capital (2024), Nature (2024), ITIF (2024)
   209→ * Finding: High-capability AI accelerates technology deployment 1.2x-2.0x
   210→ * - Drug discovery: 5-10x R&D speedup → ~1.5-2x deployment speedup
   211→ * - Enterprise investment: 2-5x acceleration when AI capability increases
   212→ * - Constraint: Physical/regulatory bottlenecks prevent instant deployment
   213→ */
   214→export function calculateDeploymentSpeed(tech: TechDefinition, region: string, gameState: GameState): number {
   215→  const factors = REGIONAL_FACTORS.get(region);
   216→  if (!factors) return 1.0;
   217→
   218→  let speed = factors.deploymentSpeed;
   219→
   220→  // Adjust based on regional relevance
   221→  const relevance = calculateRegionalRelevance(tech, region);
   222→  speed *= (0.5 + relevance); // 0.5x to 1.5x based on relevance
   223→
   224→  // Adjust based on economic capacity
   225→  speed *= (0.5 + factors.economicCapacity); // 0.5x to 1.5x based on wealth
   226→
   227→  // Adjust based on infrastructure
   228→  speed *= (0.7 + factors.infrastructure * 0.6); // 0.7x to 1.3x based on infrastructure
   229→
   230→  // Adjust based on political stability
   231→  speed *= (0.8 + factors.politicalStability * 0.4); // 0.8x to 1.2x based on stability
   232→
   233→  // === FIX #9: AI CAPABILITY SCALING ===
   234→  // Research: McKinsey (2024) - 2-5x enterprise investment acceleration
   235→  //           Foundation Capital (2024) - "rapid adoption cycle" with AI
   236→  //           Nature (2024) - Drug discovery 5-10x speedup
